Here's an implementation of the Template Method design pattern for sorting algorithms in Python:

```python
from abc import ABC, abstractmethod

class SortAlgorithm(ABC):
    def sort(self, array):
        self._sort(array)

    @abstractmethod
    def _sort(self, array):
        pass

    @abstractmethod
    def compare(self, a, b):
        pass

    @abstractmethod
    def swap(self, a, b):
        pass


class BubbleSort(SortAlgorithm):
    def _sort(self, array):
        n = len(array)
        for i in range(n):
            for j in range(0, n - i - 1):
                if self.compare(array[j], array[j + 1]):
                    self.swap(array[j], array[j + 1])

    def compare(self, a, b):
        return a < b

    def swap(self, a, b):
        a, b = b, a


class SelectionSort(SortAlgorithm):
    def _sort(self, array):
        n = len(array)
        for i in range(n):
            min_idx = i
            for j in range(i + 1, n):
                if self.compare(array[j], array[min_idx]):
                    min_idx = j
            self.swap(array[i], array[min_idx])

    def compare(self, a, b):
        return a < b

    def swap(self, a, b):
        a, b = b, a


# Testing the sorting algorithms
if __name__ == "__main__":
    array1 = [64, 34, 25, 12, 22, 11, 90]
    bubble_sort = BubbleSort()
    bubble_sort.sort(array1)
    print("Sorted array (Bubble Sort):", array1)

    array2 = ["dog", "cat", "apple", "banana", "elephant"]
    selection_sort = SelectionSort()
    selection_sort.sort(array2)
    print("Sorted array (Selection Sort):", array2)
```

